import { loadFont } from "@remotion/google-fonts/Inter";
import { forwardRef, useEffect, useImperativeHandle, useRef, useState, type CSSProperties, type ComponentProps } from "react";
import { Easing, Interactive, Sequence, continueRender, delayRender, interpolate, interpolateColors, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const { fontFamily: INTER } = loadFont("normal", {
  weights: ["100", "900"],
  subsets: ["latin"],
});

interface SelectionSnapProps {
  text?: string;
  fontSize?: number;
  fontFamily?: string;
  fromWeight?: number;
  toWeight?: number;
  color?: string;
  accent?: string;
  selectionColor?: string;
  badge?: boolean;
  speed?: number;
  className?: string;
}

const selectionSnapDefaults = {
  text: "Frame",
  fontSize: 150,
  fontFamily: INTER,
  fromWeight: 100,
  toWeight: 900,
  color: "#fafafa",
  accent: "#D97757",
  selectionColor: "#0d99ff",
  badge: true,
  speed: 1,
} satisfies Required<Omit<SelectionSnapProps, "className">>;

/** Frame on the 30 fps timeline where every channel has come to rest. */
const selectionSnapLength = 38;

/** Padding around the word, in em: the loose viewfinder and the snapped box. */
const selectionSnapPadding = {
  loose: { x: 1.1, y: 0.9 },
  tight: { x: 0.12, y: 0 },
} as const;

/** Corners first, then edge midpoints, as fractions of the box. */
const selectionSnapHandles = [
  [0, 0],
  [1, 0],
  [1, 1],
  [0, 1],
  [0.5, 0],
  [1, 0.5],
  [0.5, 1],
  [0, 0.5],
] as const;

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const easeOutCubic = Easing.out(Easing.cubic);
const easeInOutCubic = Easing.inOut(Easing.cubic);
const snapEase = Easing.bezier(0.34, 1.3, 0.64, 1);
const popEase = Easing.out(Easing.back(1.7));

function finite(value: number | undefined, fallback: number) {
  return typeof value === "number" && Number.isFinite(value) ? value : fallback;
}

/** Back-eased 0 → 1 over `duration` frames from `start`, never below 0. */
function pop(t: number, start: number, duration: number) {
  return Math.max(
    0,
    interpolate(t, [start, start + duration], [0, 1], {
      ...CLAMP,
      easing: popEase,
    }),
  );
}

/** Maps a composition frame onto the 30 fps timeline, scaled by `speed`. */
function getSelectionSnapTime(
  frame: number,
  options: { fps?: number; speed?: number } = {},
) {
  const fps = Math.max(1, finite(options.fps, 30));
  const speed = Math.max(0, finite(options.speed, 1));
  return (Math.max(0, finite(frame, 0)) * 30 * speed) / fps;
}

interface SelectionSnapState {
  /** Word and brackets fading in, 0..1. */
  intro: number;
  /** Viewfinder settle scale. */
  bracketScale: number;
  /** Loose (0) to tight (1) padding. Overshoots past 1 on the snap. */
  snap: number;
  /** Weight progress, 0..1. */
  weight: number;
  /** Color progress toward the accent, 0..1. */
  tint: number;
  /** Bracket arms growing along the edges; 1 closes them into a box. */
  edges: number;
  /** Scale of each handle, in `selectionSnapHandles` order. */
  handles: number[];
  /** Badge entrance, 0..1 with overshoot. */
  badge: number;
  /** Badge readout progress, 0..1. */
  count: number;
}

function getSelectionSnapState(t: number): SelectionSnapState {
  return {
    intro: interpolate(t, [0, 8], [0, 1], { ...CLAMP, easing: easeOutCubic }),
    bracketScale: interpolate(t, [0, 8], [1.06, 1], {
      ...CLAMP,
      easing: easeOutCubic,
    }),
    snap: interpolate(t, [14, 28], [0, 1], { ...CLAMP, easing: snapEase }),
    weight: interpolate(t, [14, 30], [0, 1], {
      ...CLAMP,
      easing: easeInOutCubic,
    }),
    tint: interpolate(t, [18, 30], [0, 1], {
      ...CLAMP,
      easing: easeInOutCubic,
    }),
    edges: interpolate(t, [16, 26], [0, 1], {
      ...CLAMP,
      easing: easeInOutCubic,
    }),
    handles: selectionSnapHandles.map((_, i) => pop(t, 24 + i, 5)),
    badge: pop(t, 24, 8),
    count: interpolate(t, [24, 38], [0, 1], { ...CLAMP, easing: easeOutCubic }),
  };
}

/** Padding in em for a snap progress. */
function getSelectionSnapPadding(snap: number) {
  const { loose, tight } = selectionSnapPadding;
  return {
    x: loose.x + (tight.x - loose.x) * snap,
    y: loose.y + (tight.y - loose.y) * snap,
  };
}

/** Size of the snapped box in reference px, from the word's final width. */
function getSelectionSnapSize(textWidth: number, fontSize: number) {
  const { tight } = selectionSnapPadding;
  return {
    width: Math.round(textWidth + 2 * tight.x * fontSize),
    height: Math.round(fontSize * (1 + 2 * tight.y)),
  };
}

function useTextWidth(text: string, font: string) {
  const [width, setWidth] = useState<number | null>(null);

  useEffect(() => {
    const handle = delayRender("selection-snap: measuring the word");
    let released = false;
    const release = () => {
      if (released) return;
      released = true;
      continueRender(handle);
    };
    const measure = () => {
      if (released) return;
      const ctx = document.createElement("canvas").getContext("2d");
      if (ctx) {
        ctx.font = font;
        setWidth(ctx.measureText(text).width);
      }
      release();
    };
    document.fonts.load(font, text).then(measure, measure);
    return release;
  }, [text, font]);

  return width;
}

function SelectionSnapBase({
  text = selectionSnapDefaults.text,
  fontSize = selectionSnapDefaults.fontSize,
  fontFamily = selectionSnapDefaults.fontFamily,
  fromWeight = selectionSnapDefaults.fromWeight,
  toWeight = selectionSnapDefaults.toWeight,
  color = selectionSnapDefaults.color,
  accent = selectionSnapDefaults.accent,
  selectionColor = selectionSnapDefaults.selectionColor,
  badge = selectionSnapDefaults.badge,
  speed = selectionSnapDefaults.speed,
  className,
}: SelectionSnapProps) {
  const frame = useCurrentFrame();
  const { fps, height } = useVideoConfig();
  const unit = height / 720;
  const t = getSelectionSnapTime(frame, { fps, speed });
  const state = getSelectionSnapState(t);

  const size = fontSize * unit;
  const pad = getSelectionSnapPadding(state.snap);
  const weight = fromWeight + (toWeight - fromWeight) * state.weight;
  const stroke = Math.max(1, 1.5 * unit);
  const arm = 0.16 * size;
  const handleSize = 9 * unit;
  const finalWidth = useTextWidth(
    text,
    `${toWeight} ${fontSize}px ${fontFamily}`,
  );
  const readout =
    finalWidth === null ? null : getSelectionSnapSize(finalWidth, fontSize);

  // Percentages resolve against the box width for `width` and its height for
  // `height`, so one expression grows every arm to its edge's midpoint.
  const along = `calc(${arm}px + (50% - ${arm}px) * ${state.edges})`;
  const arms: CSSProperties[] = [
    { top: 0, left: 0, width: along, height: stroke },
    { top: 0, right: 0, width: along, height: stroke },
    { bottom: 0, left: 0, width: along, height: stroke },
    { bottom: 0, right: 0, width: along, height: stroke },
    { top: 0, left: 0, width: stroke, height: along },
    { bottom: 0, left: 0, width: stroke, height: along },
    { top: 0, right: 0, width: stroke, height: along },
    { bottom: 0, right: 0, width: stroke, height: along },
  ];

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          position: "relative",
          display: "inline-block",
          padding: `${pad.y * size}px ${pad.x * size}px`,
        }}
      >
        <span
          style={{
            display: "block",
            whiteSpace: "pre",
            fontFamily,
            fontSize: size,
            lineHeight: 1,
            fontWeight: Math.round(weight / 100) * 100,
            fontVariationSettings: `"wght" ${weight.toFixed(2)}`,
            color: interpolateColors(state.tint, [0, 1], [color, accent]),
            opacity: state.intro,
          }}
        >
          {text}
        </span>
        <div
          style={{
            position: "absolute",
            inset: 0,
            opacity: state.intro,
            transform: `scale(${state.bracketScale})`,
          }}
        >
          {arms.map((style, i) => (
            <div
              key={i}
              style={{
                position: "absolute",
                background: selectionColor,
                ...style,
              }}
            />
          ))}
          {selectionSnapHandles.map(([x, y], i) => (
            <div
              key={`${x}-${y}`}
              style={{
                position: "absolute",
                left: `${x * 100}%`,
                top: `${y * 100}%`,
                width: handleSize,
                height: handleSize,
                boxSizing: "border-box",
                background: "#ffffff",
                border: `${stroke}px solid ${selectionColor}`,
                transform: `translate(-50%, -50%) scale(${state.handles[i]})`,
              }}
            />
          ))}
        </div>
        {badge && readout ? (
          <div
            style={{
              position: "absolute",
              left: "50%",
              top: `calc(100% + ${12 * unit}px)`,
              padding: `${3 * unit}px ${7 * unit}px`,
              borderRadius: 4 * unit,
              background: selectionColor,
              color: "#ffffff",
              fontFamily: INTER,
              fontSize: 14 * unit,
              lineHeight: 1.2,
              fontWeight: 600,
              fontVariationSettings: '"wght" 600',
              fontVariantNumeric: "tabular-nums",
              whiteSpace: "nowrap",
              opacity: Math.min(1, state.badge),
              transform: `translate(-50%, ${(1 - state.badge) * 8 * unit}px) scale(${0.6 + 0.4 * state.badge})`,
              transformOrigin: "50% 0",
            }}
          >
            {Math.round(readout.width * state.count)} ×{" "}
            {Math.round(readout.height * state.count)}
          </div>
        ) : null}
      </div>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default: "Frame",
    description: "Text",
  },
  color: {
    type: "color",
    default: "#fafafa",
    description: "Start color",
  },
  accent: {
    type: "color",
    default: "#ff4d1a",
    description: "Accent",
  },
  selectionColor: {
    type: "color",
    default: "#3d5afe",
    description: "Selection",
  },
  fontSize: {
    type: "number",
    default: 150,
    min: 60,
    max: 260,
    step: 2,
    description: "Font size",
    hiddenFromList: false,
  },
  fromWeight: {
    type: "number",
    default: 100,
    min: 100,
    max: 900,
    step: 50,
    description: "From weight",
    hiddenFromList: false,
  },
  toWeight: {
    type: "number",
    default: 900,
    min: 100,
    max: 900,
    step: 50,
    description: "To weight",
    hiddenFromList: false,
  },
  badge: {
    type: "boolean",
    default: true,
    description: "Size badge",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","color","accent","selectionColor","fontSize","fromWeight","toWeight","badge","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "Frame",
  color: "#fafafa",
  accent: "#ff4d1a",
  selectionColor: "#3d5afe",
  fontSize: 150,
  fromWeight: 100,
  toWeight: 900,
  badge: true,
  speed: 1,
};

type SelectionSnapElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof SelectionSnapBase>;

const SelectionSnapInner = forwardRef<
  HTMLDivElement,
  SelectionSnapElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<SelectionSnap>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <SelectionSnapBase
          {...(componentProps as unknown as ComponentProps<typeof SelectionSnapBase>)}
        />
      </div>
    </Sequence>
  );
});

export const SelectionSnap = Interactive.withSchema({
  Component: SelectionSnapInner,
  componentName: "<SelectionSnap>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
